//! Raw, unsafe bindings to ggml, generated by bindgen at build time from the submodule at
//! `af97976c7810cdabb1863172f31c432dab767de7`. Nothing here is safe; a wrapper belongs in another crate.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// The ggml commit these bindings were generated from.
pub const GGML_COMMIT: &str = "af97976c7810cdabb1863172f31c432dab767de7";

/// `GGML_PAD` is a function-like macro, which bindgen does not translate.
pub const fn pad_to(x: i64, n: i64) -> i64 {
    (x + n - 1) & !(n - 1)
}
